'use strict';
window.GameFX=(()=>{
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function battle(previous,next,role){const board=document.querySelector('.battle-board');if(!board)return;if(!previous){board.classList.add('arena-enter');return;}if(next.round===previous.round)return;const attacker=previous.turn,sourceIndex=previous.active[attacker],targetSide=1-attacker;const side=team=>board.querySelector('[data-team="'+team+'"]');const source=side(attacker)?.querySelector('[data-index="'+sourceIndex+'"]');let damage=0,target=null;next.teams[targetSide].forEach((card,i)=>{const loss=previous.teams[targetSide][i].hp-card.hp;if(loss>0){damage=loss;target=side(targetSide)?.querySelector('[data-index="'+i+'"]');}});
if(target&&next.active[targetSide]!==previous.active[targetSide]&&!reduced()){const incoming=side(targetSide).querySelector('.arena-fighter'),old=target.cloneNode(true),r=incoming.getBoundingClientRect(),br=board.getBoundingClientRect();old.className='battle-unit arena-fighter knockout-ghost';old.style.cssText='position:absolute;left:'+(r.left-br.left)+'px;top:'+(r.top-br.top)+'px;width:'+r.width+'px;height:'+r.height+'px;z-index:9;pointer-events:none';board.append(old);incoming.style.visibility='hidden';target=old;setTimeout(()=>{old.remove();incoming.style.visibility='';incoming.classList.add('card-swap');},950);}
const lastLog=next.log[next.log.length-1]||'',guard=lastLog.includes('se protège'),change=lastLog.includes('Changement');if(!reduced()){board.classList.remove('arena-enter');source?.classList.add(change?'card-swap':guard?'card-guard':next.lastMove?.action==='focus'?'card-focus':'card-attack');if(target){target.classList.add('card-hit');const a=source.getBoundingClientRect(),b=target.getBoundingClientRect(),r=board.getBoundingClientRect(),dx=b.x+b.width/2-(a.x+a.width/2),dy=b.y+b.height/2-(a.y+a.height/2);source.style.setProperty('--lunge-x',dx*.72+'px');source.style.setProperty('--lunge-y',dy*.72+'px');const beam=document.createElement('i');beam.className='attack-beam '+BrawlCore.cards.find(c=>c.id===previous.teams[attacker][sourceIndex].id).element;beam.style.cssText='left:'+(a.x+a.width/2-r.x)+'px;top:'+(a.y+a.height/2-r.y)+'px;--dx:'+dx+'px;--dy:'+dy+'px';board.append(beam);setTimeout(()=>beam.remove(),900);for(let i=0;i<12;i++){const dot=document.createElement('i');dot.className='impact-particle';const angle=i/12*Math.PI*2;dot.style.cssText='left:'+(b.x+b.width/2-r.x)+'px;top:'+(b.y+b.height/2-r.y)+'px;--px:'+Math.cos(angle)*65+'px;--py:'+Math.sin(angle)*65+'px;background:'+['#ffe064','#b8a2ff','#ffae93'][i%3];board.append(dot);setTimeout(()=>dot.remove(),1100);}}
const fx=document.createElement('div');fx.className='duel-callout';fx.textContent=next.lastMove?.action==='focus'?'PRÉPARATION !':next.lastMove?.action==='pierce'?'PERCÉE !':change?'CHANGEMENT !':guard?'PROTECTION !':lastLog.includes('pouvoir')?'POUVOIR !':'ATTAQUE !';board.append(fx);setTimeout(()=>fx.remove(),1000);}
if(target&&damage){const number=document.createElement('b');number.className='damage-number';number.textContent='−'+damage;target.append(number);setTimeout(()=>number.remove(),1200);}if(next.winner!==null){const win=document.createElement('div');win.className='victory-banner';win.textContent=next.winner===2?'BEAU DUEL !':next.winner===role?'VICTOIRE !':'BIEN JOUÉ !';board.append(win);setTimeout(()=>win.remove(),2200);}}
function reveal(card){const image=card.image?'<img src="'+esc(card.image)+'" alt="'+esc(card.name)+'">':'<span>'+card.emoji+'</span>';return '<div class="modal-center capsule-reveal"><div class="eyebrow">UN NOUVEAU TRÉSOR</div><h2>Une carte pour tes aventures !</h2><div class="reveal-rays"></div><div class="reveal-card">'+image+'</div><h3>'+esc(card.name)+'</h3><p>'+ (card.franchise==='lorcana'?'Disney Lorcana':'Pokémon')+' · À restaurer puis à emmener en arène.</p><button class="btn purple" data-action="go" data-arg="cards">Voir ma collection</button></div>';}
return {battle,reveal};
})();
